#!/usr/bin/env node
/**
 * CAUI token generator — tokens.json is the single source of truth.
 *   node scripts/build-tokens.mjs          → write generated files
 *   node scripts/build-tokens.mjs --check  → exit 1 if generated files are stale (CI)
 */
import { readFileSync, writeFileSync, existsSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { dirname, join } from 'node:path';

const root = join(dirname(fileURLToPath(import.meta.url)), '..');
const T = JSON.parse(readFileSync(join(root, 'src/lib/tokens/tokens.json'), 'utf8'));
const HEADER = 'GENERATED by scripts/build-tokens.mjs from tokens.json — DO NOT EDIT BY HAND.';

const hexRgb = (h) => {
  const x = h.replace('#', '');
  const f = x.length === 3 ? x.split('').map((c) => c + c).join('') : x;
  return [0, 2, 4].map((i) => parseInt(f.slice(i, i + 2), 16));
};
const lum = (h) => {
  const [r, g, b] = hexRgb(h).map((v) => {
    const c = v / 255;
    return c <= 0.03928 ? c / 12.92 : ((c + 0.055) / 1.055) ** 2.4;
  });
  return 0.2126 * r + 0.7152 * g + 0.0722 * b;
};
export const contrast = (a, b) => {
  const [hi, lo] = [lum(a), lum(b)].sort((x, y) => y - x);
  return (hi + 0.05) / (lo + 0.05);
};
/** Text colour on a brand-filled surface: whichever of white / near-black gives the higher contrast. */
const onBrand = (h) => (contrast(h, '#ffffff') >= contrast(h, '#09090b') ? '#ffffff' : '#09090b');
const glow = (h, a = 0.15) => `rgba(${hexRgb(h).join(', ')}, ${a})`;
const vars = (obj, prefix = '--ca-') => Object.entries(obj).map(([k, v]) => `  ${prefix}${k}: ${v};`).join('\n');

function css() {
  const b = T.defaultBrand;
  const out = [`/* ${HEADER} */`, `/* ${T.name} v${T.version} — ${T.apps.length} CA apps */`, ''];
  out.push(':root {', '  /* Surfaces & text (light) */', vars(T.modes.light), '');
  out.push('  /* Brand (default) */', `  --ca-brand: ${b};`, `  --ca-brand-glow: ${glow(b)};`, `  --ca-brand-contrast: ${onBrand(b)};`, '');
  out.push('  /* Semantic */', vars(T.semantic), '');
  out.push('  /* Radius */', vars(T.radius, '--ca-radius-'), '');
  out.push('  /* Spacing */', vars(T.spacing, '--ca-space-'), '');
  out.push('  /* Typography */', `  --ca-font-sans: ${T.font.sans};`, `  --ca-font-mono: ${T.font.mono};`, '');
  out.push('  /* Motion */', vars(T.motion.duration, '--ca-motion-duration-'), vars(T.motion.easing, '--ca-motion-easing-'));
  out.push('}', '', '.dark {', vars(T.modes.dark), '}', '');
  T.apps.forEach((a, i) => {
    out.push(`/* ${i + 1}. ${a.name} — ${a.role} */`, `[data-theme="${a.id}"] {`);
    out.push(`  --ca-brand: ${a.brand};`, `  --ca-brand-glow: ${glow(a.brand, a.glowAlpha)};`, `  --ca-brand-contrast: ${onBrand(a.brand)};`, '}', '');
  });
  return out.join('\n');
}

function appsTs() {
  const rows = T.apps.map((a) =>
    `  {\n    id: ${JSON.stringify(a.id)},\n    name: ${JSON.stringify(a.name)},\n    role: ${JSON.stringify(a.role)},\n    color: ${JSON.stringify(a.brand)},\n    glow: ${JSON.stringify(glow(a.brand, a.glowAlpha))},\n    contrast: ${JSON.stringify(onBrand(a.brand))},\n    characteristics: ${JSON.stringify(a.characteristics)}\n  }`
  );
  return `// ${HEADER}\nimport type { AppThemeInfo } from './index';\n\nexport const CA_APPS_THEMES: AppThemeInfo[] = [\n${rows.join(',\n')}\n];\n\nexport type CaAppId = ${T.apps.map((a) => JSON.stringify(a.id)).join(' | ')};\n`;
}

const targets = {
  'src/lib/tokens/tokens.css': css(),
  'src/lib/theme/apps.generated.ts': appsTs(),
};

const check = process.argv.includes('--check');
let stale = 0;
for (const [rel, content] of Object.entries(targets)) {
  const p = join(root, rel);
  const current = existsSync(p) ? readFileSync(p, 'utf8') : '';
  if (current === content) continue;
  if (check) {
    console.error(`✗ stale: ${rel} (run \`pnpm tokens\`)`);
    stale++;
  } else {
    writeFileSync(p, content);
    console.log(`✓ wrote ${rel}`);
  }
}
if (check && stale) process.exit(1);
if (check) console.log('✓ tokens up to date');
